import { registerBidder } from "prebid-core/adapters/bidderFactory.js";
import { BANNER } from "prebid-core/mediaTypes.js";

function pageType() {
    return document.documentElement.dataset.pageType || "home";
}

function slotName(bid) {
    return bid.params.slot;
}

// Builds and registers a bidder adapter. `endpoint` names the static response
// file, `buildPayload` shapes the (unsent) request body and `parse` turns the
// response document into a list of { slot, cpm, currency, width, height, ad, creativeId, domain, dealId }.
export function defineBidder({ code, endpoint, buildPayload, parse }) {
    const spec = {
        code,
        supportedMediaTypes: [BANNER],

        isBidRequestValid(bid) {
            return !!(bid.params && bid.params.slot && bid.params.placementId);
        },

        buildRequests(validBidRequests, bidderRequest) {
            const payload = buildPayload(validBidRequests, bidderRequest);
            return {
                method: "GET",
                url: `data/tp/bids/${endpoint}-${pageType()}.json`,
                payload,
                bids: validBidRequests,
            };
        },

        interpretResponse(serverResponse, request) {
            const entries = parse(serverResponse.body || {});
            const bySlot = new Map();
            for (const bid of request.bids)
                bySlot.set(slotName(bid), bid);
            const bids = [];
            for (const entry of entries) {
                const bid = bySlot.get(entry.slot);
                if (!bid)
                    continue;
                bids.push({
                    requestId: bid.bidId,
                    cpm: entry.cpm,
                    currency: entry.currency,
                    width: entry.width,
                    height: entry.height,
                    ad: entry.ad,
                    ttl: 300,
                    creativeId: entry.creativeId,
                    netRevenue: true,
                    dealId: entry.dealId,
                    mediaType: BANNER,
                    meta: { advertiserDomains: [entry.domain] },
                });
            }
            return bids;
        },
    };
    registerBidder(spec);
    return spec;
}

export function basePayload(code, bids, bidderRequest) {
    return {
        id: bidderRequest.auctionId,
        bidder: code,
        site: { page: location.pathname, domain: location.hostname },
        device: { w: screen.width, h: screen.height, language: navigator.language },
        regs: { gdpr: bidderRequest.gdprConsent ? Number(!!bidderRequest.gdprConsent.gdprApplies) : 0 },
        imps: bids.map((bid) => ({
            id: bid.bidId,
            slot: bid.params.slot,
            placement: bid.params.placementId,
            sizes: bid.mediaTypes.banner.sizes,
            floor: bid.getFloor ? bid.getFloor({ currency: "EUR", mediaType: BANNER, size: "*" }) : null,
        })),
    };
}
