import { defineBidder, basePayload } from "../mockBidder.js";

defineBidder({
    code: "betaBidder",
    endpoint: "beta",
    buildPayload: (bids, request) => ({ ...basePayload("betaBidder", bids, request), v: 2 }),
    parse(body) {
        if (body.status !== "ok")
            return [];
        return body.bids.map((bid) => ({
            slot: bid.slot,
            cpm: bid.cpm,
            currency: bid.currency,
            width: bid.width,
            height: bid.height,
            ad: bid.markup,
            creativeId: bid.creative_id,
            domain: bid.domain,
        }));
    },
});
