import { defineBidder, basePayload } from "../mockBidder.js";

defineBidder({
    code: "alphaBidder",
    endpoint: "alpha",
    buildPayload: (bids, request) => basePayload("alphaBidder", bids, request),
    parse(body) {
        const out = [];
        for (const seat of body.seatbid || []) {
            for (const bid of seat.bid) {
                out.push({
                    slot: bid.impid,
                    cpm: bid.price,
                    currency: body.cur,
                    width: bid.w,
                    height: bid.h,
                    ad: bid.adm,
                    creativeId: bid.crid,
                    domain: bid.adomain[0],
                    dealId: bid.dealid,
                });
            }
        }
        return out;
    },
});
