import { defineBidder, basePayload } from "../mockBidder.js";

defineBidder({
    code: "gammaBidder",
    endpoint: "gamma",
    buildPayload: (bids, request) => ({ ...basePayload("gammaBidder", bids, request), units: bids.length }),
    parse(body) {
        const out = [];
        for (const placement of body.placements || []) {
            if (!placement.bid)
                continue;
            out.push({
                slot: placement.name,
                cpm: placement.bid.micros / 1e6,
                currency: placement.bid.currency,
                width: placement.bid.size[0],
                height: placement.bid.size[1],
                ad: placement.bid.html,
                creativeId: placement.bid.id,
                domain: placement.bid.advertiser,
            });
        }
        return out;
    },
});
